#include <iostream>
#include <string>

class Account {
private:
    int balance{0};

public:
    explicit Account(int initialBalance) {
        if (initialBalance >= 0) {
            balance = initialBalance;
        } else {
            balance = 0;
            std::cout << "Error: Initial balance was invalid.\n";
        }
    }

    void credit(int amount) {
        if (amount > 0) {
            balance += amount;
        }
    }

    void debit(int amount) {
        if (amount > balance) {
            std::cout << "Debit amount exceeded account balance.\n";
        } else if (amount > 0) {
            balance -= amount;
        }
    }

    int getBalance() const {
        return balance;
    }
};

class Date {
private:
    int month{1};
    int day{1};
    int year{2000};

public:
    Date(int m, int d, int y) : day{d}, year{y} {
        setMonth(m);
    }

    void setMonth(int m) {
        if (m >= 1 && m <= 12) {
            month = m;
        } else {
            month = 1;
        }
    }

    int getMonth() const { return month; }
    void setDay(int d) { day = d; }
    int getDay() const { return day; }
    void setYear(int y) { year = y; }
    int getYear() const { return year; }

    void displayDate() const {
        std::cout << month << "/" << day << "/" << year << "\n";
    }
};

int main() {
    Account acc1(100);
    Account acc2(-20);

    acc1.credit(50);
    acc1.debit(30);
    acc1.debit(150);

    std::cout << "Account 1 balance: " << acc1.getBalance() << "\n";
    std::cout << "Account 2 balance: " << acc2.getBalance() << "\n";

    Date d1(14, 25, 2026);
    Date d2(7, 4, 2026);
    std::cout << "Date 1: ";
    d1.displayDate();
    std::cout << "Date 2: ";
    d2.displayDate();

    return 0;
}

#include <iostream>
#include <string>

class HeartRates {
private:
    std::string firstName;
    std::string lastName;
    int birthMonth{1};
    int birthDay{1};
    int birthYear{1900};

public:
    HeartRates(std::string first, std::string last, int m, int d, int y)
        : firstName{std::move(first)}, lastName{std::move(last)},
          birthMonth{m}, birthDay{d}, birthYear{y} {}

    void setFirstName(const std::string& first) { firstName = first; }
    std::string getFirstName() const { return firstName; }

    void setLastName(const std::string& last) { lastName = last; }
    std::string getLastName() const { return lastName; }

    void setBirthMonth(int m) { birthMonth = m; }
    int getBirthMonth() const { return birthMonth; }

    void setBirthDay(int d) { birthDay = d; }
    int getBirthDay() const { return birthDay; }

    void setBirthYear(int y) { birthYear = y; }
    int getBirthYear() const { return birthYear; }

    int getAge(int currentMonth, int currentDay, int currentYear) const {
        int age = currentYear - birthYear;
        if (currentMonth < birthMonth || (currentMonth == birthMonth && currentDay < birthDay)) {
            --age;
        }
        return age;
    }

    int getMaximumHeartRate(int age) const {
        return 220 - age;
    }

    void printTargetHeartRate(int maxHeartRate) const {
        int minTarget = maxHeartRate * 50 / 100;
        int maxTarget = maxHeartRate * 85 / 100;
        std::cout << minTarget << " - " << maxTarget << " bpm";
    }
};

int main() {
    HeartRates person("Alex", "Smith", 6, 15, 1995);

    // Using a deterministic reference current date: 2026-03-30
    int currentM = 3;
    int currentD = 30;
    int currentY = 2026;

    int age = person.getAge(currentM, currentD, currentY);
    int maxHr = person.getMaximumHeartRate(age);

    std::cout << "Name: " << person.getFirstName() << " " << person.getLastName() << "\n";
    std::cout << "DOB: " << person.getBirthMonth() << "/" << person.getBirthDay() << "/" << person.getBirthYear() << "\n";
    std::cout << "Age: " << age << "\n";
    std::cout << "Max Heart Rate: " << maxHr << " bpm\n";
    std::cout << "Target Heart Rate: ";
    person.printTargetHeartRate(maxHr);
    std::cout << "\n";

    return 0;
}
